int __attribute__((noipa)) f(unsigned a, int b) {
  if (a < 0)
    __builtin_unreachable();
  if (a > 30)
    __builtin_unreachable();
  int t = a;
  if (b)
    t = 100;
  else if (a != 0)
    t = a;
  else
    t = 1;
  return t;
}

